/* AlertDialog: the modal glass (--modal-* tokens) at a small, fixed width.
   Everything in the header sits on one left edge: the tile, the title and
   the description stack under each other, flush left. */

.root {
  position: fixed;
  inset: 0;
  z-index: var(--z-modal);
  display: grid;
  place-items: center;
  padding: 16px;
}

.scrim {
  position: absolute;
  inset: 0;
  background: var(--modal-scrim);
  -webkit-backdrop-filter: var(--modal-scrim-blur);
  backdrop-filter: var(--modal-scrim-blur);
  animation: fade-in var(--dur-slow) var(--ease);
}

.root[data-state="closed"] .scrim,
.root[data-state="closed"] .panel {
  opacity: 0;
  transition: opacity var(--dur-slow) var(--ease);
}

.panel {
  position: relative;
  display: flex;
  flex-direction: column;
  width: min(var(--alert-dialog-width, 440px), 100%);
  overflow: hidden;
  background: var(--modal-surface);
  -webkit-backdrop-filter: var(--modal-blur);
  backdrop-filter: var(--modal-blur);
  border-radius: var(--alert-dialog-radius, var(--r-xl));
  box-shadow: var(--modal-shadow);
  color: var(--ink-body);
  outline: none;
  animation: pop-in var(--dur-slow) var(--ease-out);
}

/* Inline: the same panel standing in the page, no motion. */
.inline {
  animation: none;
}

.header {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 6px;
  padding: calc(22px * var(--density)) calc(24px * var(--density)) 0;
}

.tile {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 40px;
  height: 40px;
  margin-bottom: 6px;
  border-radius: var(--r-md);
  background: var(--danger-fill);
  box-shadow: inset 0 0 0 1px var(--danger-line);
  color: var(--danger-ink);
}

.title {
  font-family: var(--font-display);
  font-size: var(--alert-dialog-title-size, 18px);
  font-weight: 700;
  line-height: 1.3;
  letter-spacing: var(--tracking-display);
  color: var(--ink-heading);
}

.description {
  font-size: var(--text-body);
  line-height: 1.55;
  color: var(--ink-secondary);
}

.body {
  padding: 14px calc(24px * var(--density)) 0;
  font-size: var(--text-small);
  color: var(--ink-body);
}

.footer {
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: 10px;
  padding: calc(20px * var(--density)) calc(24px * var(--density)) calc(20px * var(--density));
}

@media (max-width: 480px) {
  .footer > * {
    flex: 1 1 auto;
  }
}

@media (prefers-reduced-motion: reduce) {
  .panel {
    animation: fade-in var(--dur) linear;
  }

  .inline {
    animation: none;
  }
}

"use client";

import { useId, useRef, type ReactNode } from "react";
import { cx } from "../_internal/cx";
import { Portal } from "../_internal/portal";
import { Button } from "../Button/Button";
import { IconAlertTriangle } from "../Icon/Icon";
import { useDialogBehaviour, usePresence } from "./dialog-core";
import styles from "./AlertDialog.module.css";

export type AlertDialogProps = {
  open: boolean;
  /** Cancel, Esc. There is no scrim click: the choice must be made. */
  onCancel: () => void;
  /** The action button. Close the dialog yourself once it has run. */
  onAction: () => void;
  title: ReactNode;
  description?: ReactNode;
  /** A verb plus the object: "Delete project", never "OK". */
  actionLabel: string;
  cancelLabel?: string;
  /** danger draws the action in the danger fill and a warning tile. */
  tone?: "default" | "danger";
  /** The action is in flight: both buttons lock and the action shows a spinner. */
  busy?: boolean;
  busyLabel?: string;
  /** Extra content under the description: a short list of what changes. */
  children?: ReactNode;
  /** Render the open panel in the page flow: no portal, scrim, focus trap or scroll lock (docs, previews). */
  inline?: boolean;
  className?: string;
};

/**
 * A short, interrupting question with two answers: role="alertdialog".
 * Focus starts on Cancel, so a stray Enter never confirms; Esc cancels; Tab
 * is trapped; a click on the scrim does nothing. Use it for a single
 * confirm. For forms in a dialog use Modal, and for large irreversible
 * changes TypeToConfirmModal.
 */
export function AlertDialog(props: AlertDialogProps) {
  const present = usePresence(props.open);
  if (props.inline) return <AlertPanel {...props} open />;
  if (!present) return null;
  return <AlertPanel {...props} />;
}

function AlertPanel({
  open,
  onCancel,
  onAction,
  title,
  description,
  actionLabel,
  cancelLabel = "Cancel",
  tone = "default",
  busy,
  busyLabel,
  children,
  inline,
  className,
}: AlertDialogProps) {
  const id = useId();
  const panelRef = useRef<HTMLDivElement>(null);
  const cancelRef = useRef<HTMLButtonElement>(null);
  const { onKeyDown } = useDialogBehaviour({
    open,
    panelRef,
    onEscape: () => {
      if (!busy) onCancel();
    },
    initialFocus: cancelRef,
    enabled: !inline,
  });

  const panel = (
    <div data-slot="alert-dialog"
      ref={panelRef}
      role="alertdialog"
      aria-modal={inline ? undefined : true}
      aria-labelledby={`${id}-t`}
      aria-describedby={description ? `${id}-d` : undefined}
      aria-busy={busy || undefined}
      tabIndex={-1}
      data-surface="solid"
      data-state={open ? "open" : "closed"}
      className={cx(styles.panel, inline && styles.inline, tone === "danger" && styles.danger, className)}
      onKeyDown={onKeyDown}
    >
      <div className={styles.header}>
        {tone === "danger" ? (
          <span className={styles.tile} aria-hidden="true">
            <IconAlertTriangle size={19} />
          </span>
        ) : null}
        <h2 id={`${id}-t`} className={styles.title}>
          {title}
        </h2>
        {description ? (
          <p id={`${id}-d`} className={styles.description}>
            {description}
          </p>
        ) : null}
      </div>
      {children ? <div className={styles.body}>{children}</div> : null}
      <div className={styles.footer}>
        <Button ref={cancelRef} variant="secondary" onClick={onCancel} disabled={busy}>
          {cancelLabel}
        </Button>
        <Button variant={tone === "danger" ? "danger" : "primary"} onClick={onAction} loading={busy} loadingLabel={busyLabel}>
          {actionLabel}
        </Button>
      </div>
    </div>
  );

  if (inline) return panel;
  return (
    <Portal>
      <div className={styles.root} data-state={open ? "open" : "closed"}>
        <div className={styles.scrim} aria-hidden="true" />
        {panel}
      </div>
    </Portal>
  );
}

"use client";

import { useEffect, useRef, useState, type KeyboardEvent, type RefObject } from "react";
import { focusableWithin } from "../_internal/position";
import { useScrollLock } from "../Scroll/scroll-lock";

// Shared behaviour for the modal overlays added here (AlertDialog, Sheet,
// Drawer, CommandDialog): presence for the exit animation, focus moved in
// and returned, Tab trapped, Esc, and page scroll locked.

/** Keeps the overlay mounted for `ms` after open turns false, so it can animate out. */
export function usePresence(open: boolean, ms = 200): boolean {
  const [present, setPresent] = useState(open);
  const [prev, setPrev] = useState(open);
  if (open !== prev) {
    setPrev(open);
    if (open) setPresent(true);
  }
  useEffect(() => {
    if (open || !present) return;
    const t = window.setTimeout(() => setPresent(false), ms);
    return () => window.clearTimeout(t);
  }, [open, present, ms]);
  return present;
}

export function useDialogBehaviour({
  open,
  panelRef,
  onEscape,
  initialFocus,
  enabled = true,
}: {
  open: boolean;
  panelRef: RefObject<HTMLElement | null>;
  onEscape: () => void;
  /** Focused on open; defaults to the first focusable element, else the panel. */
  initialFocus?: RefObject<HTMLElement | null>;
  enabled?: boolean;
}) {
  const returnTo = useRef<HTMLElement | null>(null);
  useScrollLock(open && enabled);

  useEffect(() => {
    if (!open || !enabled) return;
    returnTo.current = document.activeElement as HTMLElement | null;
    const frame = requestAnimationFrame(() => {
      const p = panelRef.current;
      if (!p) return;
      (initialFocus?.current ?? focusableWithin(p)[0] ?? p).focus();
    });
    return () => {
      cancelAnimationFrame(frame);
      const back = returnTo.current;
      if (back && document.contains(back)) back.focus();
    };
    // initialFocus is a stable ref.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [open, enabled]);

  /** Put on the panel: Esc and the Tab trap. */
  const onKeyDown = (e: KeyboardEvent<HTMLElement>) => {
    if (!enabled) return;
    if (e.key === "Escape") {
      e.stopPropagation();
      e.preventDefault();
      onEscape();
      return;
    }
    if (e.key !== "Tab") return;
    const p = panelRef.current;
    if (!p) return;
    const list = focusableWithin(p);
    if (!list.length) {
      e.preventDefault();
      p.focus();
      return;
    }
    const first = list[0];
    const last = list[list.length - 1];
    if (e.shiftKey && (document.activeElement === first || document.activeElement === p)) {
      e.preventDefault();
      last.focus();
    } else if (!e.shiftKey && document.activeElement === last) {
      e.preventDefault();
      first.focus();
    }
  };

  return { onKeyDown };
}
